    {"topic": "ccma-foundational", "stem": "Hepatitis B vaccination for covered employees must be offered:", "correct": "Within 10 working days of initial assignment unless declined", "distractors": ["Only after a needlestick", "Never if employee refuses paperwork", "Only to nurses"], "explanation": "OSHA mandates HBV vaccination availability for at-risk workers.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "advanced"},
