    {"topic": "ccma-foundational", "stem": "Medical assistants typically work: (scenario 5)", "correct": "Under provider supervision within scope defined by state law and employer policy", "distractors": ["Independently performing surgery", "Prescribing controlled substances without oversight", "Interpreting all imaging independently"], "explanation": "NHA materials emphasize scope of practice and supervision.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma"], "difficulty": "beginner"},
