    {"topic": "ekg-cardiac-ap", "stem": "Adult compression depth should be at least:", "correct": "2 inches (5 cm) without exceeding 2.4 inches (6 cm)", "distractors": ["1 inch always", "3 inches minimum", "Depth does not matter"], "explanation": "AHA adult BLS guidance specifies depth at least 2 inches while avoiding excessive depth.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
