    {"topic": "ekg-cardiac-ap", "stem": "Compression-to-ventilation ratio for adult BLS with advanced airway not in place is:", "correct": "30:2", "distractors": ["15:2 for all adults", "5:1", "Continuous breaths without compressions"], "explanation": "AHA conventional CPR uses 30:2 for adults.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
