    {"topic": "ekg-cardiac-ap", "stem": "Allowing full chest recoil means:", "correct": "Letting the chest return to normal position between compressions", "distractors": ["Leaning on the chest continuously", "Removing hands for 5 seconds", "Hyperextending the spine"], "explanation": "Full recoil allows heart chambers to refill.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "beginner"},
