    {"topic": "ekg-cardiac-ap", "stem": "CPR should be started on an unresponsive patient who:", "correct": "Is not breathing normally or only gasping", "distractors": ["Has a weak pulse always", "Is speaking", "Has chest pain only"], "explanation": "AHA teaches checking responsiveness and breathing before starting compressions.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
