    {"topic": "phleb-order-draw", "stem": "The order of draw is important to prevent:", "correct": "Cross-contamination of tube additives", "distractors": ["Patient discomfort only", "Slower clotting only", "Larger bruises only"], "explanation": "CLSI GP41 describes order of draw to avoid erroneous results from additive carryover.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "intermediate"},
    {"topic": "phleb-order-draw", "stem": "The One & Only Campaign reminds clinicians to use:", "correct": "One needle and one syringe only one time per patient", "distractors": ["One syringe for multiple patients if the needle is changed", "Multi-dose vials for any patient", "The same bag of IV fluid for multiple patients"], "explanation": "CDC injection safety emphasizes single-patient use of needles and syringes.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC NPIN: One & Only Campaign — https://npin.cdc.gov/campaign/one-only-campaign"], "difficulty": "beginner"},
    {"topic": "phleb-order-draw", "stem": "After venipuncture, pressure should be applied:", "correct": "Until hemostasis is achieved without compromising circulation", "distractors": ["Only 5 seconds always", "Not needed with butterfly sets", "Only if patient requests"], "explanation": "Adequate pressure reduces hematoma risk.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "beginner"},
    {"topic": "phleb-order-draw", "stem": "When should alcohol-based hand rub be used?", "correct": "When hands are not visibly soiled, per facility policy and CDC guidance", "distractors": ["Only after touching blood", "Instead of gloves always", "Never in healthcare"], "explanation": "CDC hand hygiene guidance supports ABHR when hands are not visibly dirty.", "references": ["CDC: Guideline for Hand Hygiene in Health Care Settings — https://www.cdc.gov/infection-control/hcp/hand-hygiene/index.html", "MedlinePlus: Hand-washing — https://medlineplus.gov/ency/article/007425.htm"], "difficulty": "beginner"},
    {"topic": "phleb-order-draw", "stem": "The order of draw is important to prevent: (scenario 5)", "correct": "Cross-contamination of tube additives", "distractors": ["Patient discomfort only", "Slower clotting only", "Larger bruises only"], "explanation": "CLSI GP41 describes order of draw to avoid erroneous results from additive carryover.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "intermediate"},
    {"topic": "phleb-order-draw", "stem": "Single-dose medication vials should be:", "correct": "Used for only one patient", "distractors": ["Shared between two patients in the same room", "Recapped and stored for next day", "Used until empty regardless of patients"], "explanation": "CDC injection safety prohibits using single-dose containers for multiple patients.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
