    {"topic": "phleb-site", "stem": "The One & Only Campaign reminds clinicians to use:", "correct": "One needle and one syringe only one time per patient", "distractors": ["One syringe for multiple patients if the needle is changed", "Multi-dose vials for any patient", "The same bag of IV fluid for multiple patients"], "explanation": "CDC injection safety emphasizes single-patient use of needles and syringes.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC NPIN: One & Only Campaign — https://npin.cdc.gov/campaign/one-only-campaign"], "difficulty": "beginner"},
