    {"topic": "phleb-safety", "stem": "A safe injection does not:", "correct": "Harm the patient or expose the provider to avoidable risk", "distractors": ["Require new gloves each time", "Require a witness", "Require written consent"], "explanation": "CDC defines safe injections as those that avoid harm to patients and clinicians.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "phleb-safety", "stem": "The HIPAA Security Rule focuses on:", "correct": "Safeguards for electronic PHI", "distractors": ["Only paper records", "Only verbal conversations", "Public health statistics"], "explanation": "HHS Security Rule addresses administrative, physical, and technical safeguards for ePHI.", "references": ["HHS: HIPAA Security Rule — https://www.hhs.gov/hipaa/for-professionals/security/index.html"], "difficulty": "intermediate"},
    {"topic": "phleb-safety", "stem": "The order of draw is important to prevent: (scenario 9)", "correct": "Cross-contamination of tube additives", "distractors": ["Patient discomfort only", "Slower clotting only", "Larger bruises only"], "explanation": "CLSI GP41 describes order of draw to avoid erroneous results from additive carryover.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "intermediate"},
    {"topic": "phleb-safety", "stem": "Multi-dose vials should ideally be:", "correct": "Dedicated to a single patient when possible", "distractors": ["Left at bedside for convenience", "Shared across a clinic without labeling", "Used without date"], "explanation": "CDC recommends limiting multidose vials and dedicating to one patient when feasible.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "intermediate"},
    {"topic": "phleb-safety", "stem": "Sharps injury logs must be maintained:", "correct": "Per OSHA requirements for covered employers", "distractors": ["Only if OSHA inspects", "Only in hospitals", "Never for medical offices"], "explanation": "OSHA bloodborne pathogens standard includes recordkeeping provisions.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "advanced"},
    {"topic": "phleb-safety", "stem": "Lavender-top tubes typically contain: (scenario 12)", "correct": "EDTA anticoagulant for hematology", "distractors": ["Sodium citrate for coagulation", "Heparin for chemistry", "No additive"], "explanation": "Tube additive knowledge prevents wrong test orders.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/", "NHA: CPT certification — https://www.nhanow.com/certifications/cpt"], "difficulty": "intermediate"},
    {"topic": "phleb-safety", "stem": "Engineering controls for sharps include:", "correct": "Needleless systems and sharps containers", "distractors": ["Recapping needles routinely", "Carrying syringes in pockets", "Reusing scalpels"], "explanation": "OSHA bloodborne pathogens standard emphasizes engineering controls to reduce needlesticks.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030", "OSHA: Safety and Health Topics — Needlestick Injuries — https://www.osha.gov/needlestick"], "difficulty": "intermediate"},
    {"topic": "cpr-adult", "stem": "Adult CPR compression rate should be:", "correct": "100 to 120 compressions per minute", "distractors": ["60 to 80 per minute", "150 to 180 per minute", "As fast as possible without limit"], "explanation": "AHA recommends 100–120/min for adult compressions.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "cpr-adult", "stem": "Adult compression depth should be at least:", "correct": "2 inches (5 cm) without exceeding 2.4 inches (6 cm)", "distractors": ["1 inch always", "3 inches minimum", "Depth does not matter"], "explanation": "AHA adult BLS guidance specifies depth at least 2 inches while avoiding excessive depth.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "cpr-adult", "stem": "High-quality CPR includes chest compression fraction:", "correct": "Greater than 80% when possible", "distractors": ["Less than 20%", "Exactly 50% always", "Only during shockable rhythms"], "explanation": "AHA high-quality CPR metrics include CCF >80%.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "intermediate"},
    {"topic": "cpr-adult", "stem": "Compression-to-ventilation ratio for adult BLS with advanced airway not in place is:", "correct": "30:2", "distractors": ["15:2 for all adults", "5:1", "Continuous breaths without compressions"], "explanation": "AHA conventional CPR uses 30:2 for adults.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
    {"topic": "cpr-adult", "stem": "Minimizing interruptions in chest compressions helps:", "correct": "Maintain perfusion and improve outcomes", "distractors": ["Reduce rescuer fatigue only", "Eliminate need for defibrillation", "Replace need for epinephrine"], "explanation": "AHA emphasizes minimizing pauses to improve coronary perfusion pressure.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support", "American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "intermediate"},
    {"topic": "cpr-adult", "stem": "Allowing full chest recoil means:", "correct": "Letting the chest return to normal position between compressions", "distractors": ["Leaning on the chest continuously", "Removing hands for 5 seconds", "Hyperextending the spine"], "explanation": "Full recoil allows heart chambers to refill.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "beginner"},
    {"topic": "cpr-adult", "stem": "Rescuers should switch compressors about every:", "correct": "2 minutes or sooner if fatigued", "distractors": ["10 seconds", "15 minutes", "Never switch"], "explanation": "AHA algorithms recommend rotating compressors to maintain quality.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "intermediate"},
    {"topic": "cpr-adult", "stem": "Excessive ventilation during CPR can:", "correct": "Increase intrathoracic pressure and reduce venous return", "distractors": ["Improve outcomes always", "Replace compressions", "Prevent gastric distension entirely"], "explanation": "AHA warns against excessive ventilation during resuscitation.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "advanced"},
    {"topic": "cpr-adult", "stem": "If an advanced airway is in place during adult CPR, ventilations are typically:", "correct": "1 breath every 6 seconds without pausing compressions", "distractors": ["30:2 ratio still required", "No breaths ever", "1 breath every 30 seconds only"], "explanation": "AHA ACLS algorithm lists 10 breaths/min (every 6 s) with continuous compressions.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "advanced"},
    {"topic": "cpr-adult", "stem": "The first link in the adult out-of-hospital Chain of Survival is:", "correct": "Recognition of cardiac arrest and activation of emergency response", "distractors": ["Defibrillation before compressions always", "Medication administration", "Cooling"], "explanation": "Early recognition and EMS activation enable timely BLS and defibrillation.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
    {"topic": "cpr-adult", "stem": "AED use should begin:", "correct": "As soon as the device is available while CPR continues", "distractors": ["Only after 10 minutes of CPR", "Only if pulse is present", "Only for children"], "explanation": "Early defibrillation is a key chain-of-survival link for shockable rhythms.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
    {"topic": "cpr-adult", "stem": "CPR should be started on an unresponsive patient who:", "correct": "Is not breathing normally or only gasping", "distractors": ["Has a weak pulse always", "Is speaking", "Has chest pain only"], "explanation": "AHA teaches checking responsiveness and breathing before starting compressions.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "cpr-adult", "stem": "Hands-only CPR (compressions without breaths) is taught for:", "correct": "Adult sudden cardiac arrest by lay rescuers when unwilling to give breaths", "distractors": ["All pediatric arrests", "Drowning victims only", "Replacing all professional BLS"], "explanation": "AHA supports compression-only CPR for untrained or unwilling lay rescuers in adult arrest.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "intermediate"},
