    {"topic": "cpr-aed", "stem": "AED use should begin:", "correct": "As soon as the device is available while CPR continues", "distractors": ["Only after 10 minutes of CPR", "Only if pulse is present", "Only for children"], "explanation": "Early defibrillation is a key chain-of-survival link for shockable rhythms.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
    {"topic": "cpr-aed", "stem": "CPR should be started on an unresponsive patient who:", "correct": "Is not breathing normally or only gasping", "distractors": ["Has a weak pulse always", "Is speaking", "Has chest pain only"], "explanation": "AHA teaches checking responsiveness and breathing before starting compressions.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "cpr-aed", "stem": "Hands-only CPR (compressions without breaths) is taught for:", "correct": "Adult sudden cardiac arrest by lay rescuers when unwilling to give breaths", "distractors": ["All pediatric arrests", "Drowning victims only", "Replacing all professional BLS"], "explanation": "AHA supports compression-only CPR for untrained or unwilling lay rescuers in adult arrest.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "intermediate"},
    {"topic": "cpr-choking", "stem": "Adult CPR compression rate should be:", "correct": "100 to 120 compressions per minute", "distractors": ["60 to 80 per minute", "150 to 180 per minute", "As fast as possible without limit"], "explanation": "AHA recommends 100–120/min for adult compressions.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "cpr-choking", "stem": "Adult compression depth should be at least:", "correct": "2 inches (5 cm) without exceeding 2.4 inches (6 cm)", "distractors": ["1 inch always", "3 inches minimum", "Depth does not matter"], "explanation": "AHA adult BLS guidance specifies depth at least 2 inches while avoiding excessive depth.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "cpr-choking", "stem": "High-quality CPR includes chest compression fraction:", "correct": "Greater than 80% when possible", "distractors": ["Less than 20%", "Exactly 50% always", "Only during shockable rhythms"], "explanation": "AHA high-quality CPR metrics include CCF >80%.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "intermediate"},
    {"topic": "cpr-choking", "stem": "Compression-to-ventilation ratio for adult BLS with advanced airway not in place is:", "correct": "30:2", "distractors": ["15:2 for all adults", "5:1", "Continuous breaths without compressions"], "explanation": "AHA conventional CPR uses 30:2 for adults.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
    {"topic": "cpr-choking", "stem": "Minimizing interruptions in chest compressions helps:", "correct": "Maintain perfusion and improve outcomes", "distractors": ["Reduce rescuer fatigue only", "Eliminate need for defibrillation", "Replace need for epinephrine"], "explanation": "AHA emphasizes minimizing pauses to improve coronary perfusion pressure.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support", "American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "intermediate"},
    {"topic": "cpr-choking", "stem": "Allowing full chest recoil means:", "correct": "Letting the chest return to normal position between compressions", "distractors": ["Leaning on the chest continuously", "Removing hands for 5 seconds", "Hyperextending the spine"], "explanation": "Full recoil allows heart chambers to refill.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "beginner"},
    {"topic": "cpr-choking", "stem": "Rescuers should switch compressors about every:", "correct": "2 minutes or sooner if fatigued", "distractors": ["10 seconds", "15 minutes", "Never switch"], "explanation": "AHA algorithms recommend rotating compressors to maintain quality.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "intermediate"},
    {"topic": "cpr-choking", "stem": "Excessive ventilation during CPR can:", "correct": "Increase intrathoracic pressure and reduce venous return", "distractors": ["Improve outcomes always", "Replace compressions", "Prevent gastric distension entirely"], "explanation": "AHA warns against excessive ventilation during resuscitation.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "advanced"},
