    {"topic": "skill-injection", "stem": "Standard Precautions apply to:", "correct": "All patient care regardless of diagnosis", "distractors": ["Only patients with known HIV", "Only the operating room", "Only when gloves are worn"], "explanation": "CDC Standard Precautions are the minimum infection prevention practices for all care.", "references": ["CDC: Infection Control in Healthcare Settings (overview) — https://www.cdc.gov/infection-control/hcp/index.html", "CDC/HICPAC: Guideline for Isolation Precautions (2007) — https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"], "difficulty": "beginner"},
    {"topic": "skill-injection", "stem": "A temperature excursion in vaccine storage requires:", "correct": "Documentation and consultation with immunization program guidance", "distractors": ["Immediate discard without review always", "No action if refrigerator feels cold", "Mixing vaccines to balance temperature"], "explanation": "CDC toolkit outlines steps when storage units go out of range.", "references": ["CDC: Vaccine Storage and Handling Toolkit — https://www.cdc.gov/vaccines/hcp/admin/storage/toolkit/index.html"], "difficulty": "advanced"},
    {"topic": "skill-injection", "stem": "High-alert medications require: (scenario 3)", "correct": "Extra precautions per institutional policy", "distractors": ["No special labeling", "Verbal orders only", "Storage in patient rooms unlocked"], "explanation": "FDA medication safety resources highlight risk reduction strategies.", "references": ["FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "intermediate"},
    {"topic": "skill-injection", "stem": "When should alcohol-based hand rub be used?", "correct": "When hands are not visibly soiled, per facility policy and CDC guidance", "distractors": ["Only after touching blood", "Instead of gloves always", "Never in healthcare"], "explanation": "CDC hand hygiene guidance supports ABHR when hands are not visibly dirty.", "references": ["CDC: Guideline for Hand Hygiene in Health Care Settings — https://www.cdc.gov/infection-control/hcp/hand-hygiene/index.html", "MedlinePlus: Hand-washing — https://medlineplus.gov/ency/article/007425.htm"], "difficulty": "beginner"},
    {"topic": "skill-injection", "stem": "Vaccines must be stored: (scenario 5)", "correct": "Within manufacturer and CDC recommended temperature ranges", "distractors": ["At room temperature indefinitely", "Frozen unless label says otherwise without monitoring", "In direct sunlight"], "explanation": "CDC Vaccine Storage and Handling Toolkit defines cold chain requirements.", "references": ["CDC: Vaccine Storage and Handling Toolkit — https://www.cdc.gov/vaccines/hcp/admin/storage/toolkit/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-injection", "stem": "The rights of medication administration include: (scenario 6)", "correct": "Right patient, drug, dose, route, time, and documentation", "distractors": ["Right color of pill only", "Right pharmacy profit", "Right roommate"], "explanation": "Multiple rights frameworks reduce administration errors.", "references": ["FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program", "NHA: CCMA certification — https://www.nhanow.com/certifications/ccma"], "difficulty": "beginner"},
    {"topic": "skill-injection", "stem": "A safe injection does not:", "correct": "Harm the patient or expose the provider to avoidable risk", "distractors": ["Require new gloves each time", "Require a witness", "Require written consent"], "explanation": "CDC defines safe injections as those that avoid harm to patients and clinicians.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "skill-injection", "stem": "Needle length for vaccine IM injection depends on: (scenario 8)", "correct": "Patient age and muscle mass per CDC", "distractors": ["Always the same 1-inch needle", "Provider preference only", "Vaccine color"], "explanation": "CDC administration guidance matches needle gauge/length to site and patient size.", "references": ["CDC: Vaccine Administration — https://www.cdc.gov/vaccines/hcp/admin/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-injection", "stem": "High-alert medications require: (scenario 9)", "correct": "Extra precautions per institutional policy", "distractors": ["No special labeling", "Verbal orders only", "Storage in patient rooms unlocked"], "explanation": "FDA medication safety resources highlight risk reduction strategies.", "references": ["FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "intermediate"},
    {"topic": "skill-injection", "stem": "Multi-dose vials should ideally be:", "correct": "Dedicated to a single patient when possible", "distractors": ["Left at bedside for convenience", "Shared across a clinic without labeling", "Used without date"], "explanation": "CDC recommends limiting multidose vials and dedicating to one patient when feasible.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "intermediate"},
    {"topic": "skill-injection", "stem": "Before administering a vaccine, staff should: (scenario 11)", "correct": "Screen for contraindications and precautions per CDC guidance", "distractors": ["Skip screening if patient is in a hurry", "Use expired vaccine if refrigerator was full", "Administer in any muscle regardless of age"], "explanation": "CDC vaccine administration includes screening and valid consent processes.", "references": ["CDC: Vaccine Administration — https://www.cdc.gov/vaccines/hcp/admin/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-injection", "stem": "The rights of medication administration include: (scenario 12)", "correct": "Right patient, drug, dose, route, time, and documentation", "distractors": ["Right color of pill only", "Right pharmacy profit", "Right roommate"], "explanation": "Multiple rights frameworks reduce administration errors.", "references": ["FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program", "NHA: CCMA certification — https://www.nhanow.com/certifications/ccma"], "difficulty": "beginner"},
    {"topic": "skill-injection", "stem": "Engineering controls for sharps include:", "correct": "Needleless systems and sharps containers", "distractors": ["Recapping needles routinely", "Carrying syringes in pockets", "Reusing scalpels"], "explanation": "OSHA bloodborne pathogens standard emphasizes engineering controls to reduce needlesticks.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030", "OSHA: Safety and Health Topics — Needlestick Injuries — https://www.osha.gov/needlestick"], "difficulty": "intermediate"},
    {"topic": "skill-vitals", "stem": "Proper cuff bladder width should be about:", "correct": "40% of the arm circumference", "distractors": ["10% of arm length", "Equal to wrist width", "Twice the arm length"], "explanation": "CDC blood pressure measurement guidance stresses correct cuff size for accurate readings.", "references": ["CDC: Measuring Blood Pressure — https://www.cdc.gov/high-blood-pressure/measure/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-vitals", "stem": "The patient's arm should be supported at heart level when measuring BP to:", "correct": "Avoid systematic error in readings", "distractors": ["Increase diastolic only", "Eliminate need for stethoscope", "Speed the measurement"], "explanation": "Arm position relative to heart affects hydrostatic pressure in the vessel.", "references": ["CDC: Measuring Blood Pressure — https://www.cdc.gov/high-blood-pressure/measure/index.html"], "difficulty": "beginner"},
    {"topic": "skill-vitals", "stem": "Patient should rest quietly for how long before a clinic BP measurement?", "correct": "About 5 minutes when possible", "distractors": ["No rest needed", "At least 30 minutes", "Only 10 seconds"], "explanation": "CDC recommends resting quietly before measurement for consistency.", "references": ["CDC: Measuring Blood Pressure — https://www.cdc.gov/high-blood-pressure/measure/index.html"], "difficulty": "beginner"},
    {"topic": "skill-vitals", "stem": "Korotkoff phase I sound indicates:", "correct": "Systolic blood pressure", "distractors": ["Diastolic pressure", "Mean arterial pressure", "Pulse oximetry"], "explanation": "First tapping sound marks systolic pressure during auscultation.", "references": ["CDC: Measuring Blood Pressure — https://www.cdc.gov/high-blood-pressure/measure/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-vitals", "stem": "An improperly small cuff tends to:", "correct": "Overestimate blood pressure", "distractors": ["Underestimate blood pressure", "Have no effect", "Only affect diastolic"], "explanation": "Undersized cuffs read falsely high.", "references": ["CDC: Measuring Blood Pressure — https://www.cdc.gov/high-blood-pressure/measure/index.html"], "difficulty": "intermediate"},
