    {"topic": "skill-vitals", "stem": "Proper cuff bladder width should be about: (scenario 13)", "correct": "40% of the arm circumference", "distractors": ["10% of arm length", "Equal to wrist width", "Twice the arm length"], "explanation": "CDC blood pressure measurement guidance stresses correct cuff size for accurate readings.", "references": ["CDC: Measuring Blood Pressure — https://www.cdc.gov/high-blood-pressure/measure/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-infection", "stem": "Standard Precautions apply to:", "correct": "All patient care regardless of diagnosis", "distractors": ["Only patients with known HIV", "Only the operating room", "Only when gloves are worn"], "explanation": "CDC Standard Precautions are the minimum infection prevention practices for all care.", "references": ["CDC: Infection Control in Healthcare Settings (overview) — https://www.cdc.gov/infection-control/hcp/index.html", "CDC/HICPAC: Guideline for Isolation Precautions (2007) — https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"], "difficulty": "beginner"},
    {"topic": "skill-infection", "stem": "An Exposure Control Plan must be:", "correct": "Written and updated annually or when tasks change", "distractors": ["Verbal only", "Optional for small clinics", "Created only after an exposure"], "explanation": "OSHA requires a written exposure control plan for covered employers.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "skill-infection", "stem": "Entering a medication vial with a syringe used on a patient is called:", "correct": "Double dipping and is unsafe", "distractors": ["Standard practice in clinics", "Required for multidose vials", "Allowed if alcohol is used"], "explanation": "CDC lists double dipping among practices that spread bloodborne pathogens.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "intermediate"},
    {"topic": "skill-infection", "stem": "After a needlestick, the first priority is:", "correct": "Wash needlesticks and cuts with soap and water; flush splashes to nose/mouth with water", "distractors": ["Apply a tourniquet", "Wait until end of shift to report", "Squeeze the wound hard"], "explanation": "OSHA post-exposure steps include immediate cleansing and prompt reporting.", "references": ["OSHA: Safety and Health Topics — Needlestick Injuries — https://www.osha.gov/needlestick", "OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "skill-infection", "stem": "Transmission-Based Precautions are used:", "correct": "In addition to Standard Precautions for specific pathogens", "distractors": ["Instead of Standard Precautions", "Only in home care", "Only for surgical patients"], "explanation": "Isolation precautions supplement Standard Precautions for certain diseases.", "references": ["CDC/HICPAC: Guideline for Isolation Precautions (2007) — https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-infection", "stem": "Patients have the right under HIPAA to:", "correct": "Access and request amendments to their health records", "distractors": ["Delete all medical records permanently", "Hide records from treating clinicians", "Avoid all disclosures including treatment"], "explanation": "HHS describes individual rights to access, copy, and request correction of PHI.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-infection", "stem": "A safe injection does not:", "correct": "Harm the patient or expose the provider to avoidable risk", "distractors": ["Require new gloves each time", "Require a witness", "Require written consent"], "explanation": "CDC defines safe injections as those that avoid harm to patients and clinicians.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "skill-infection", "stem": "The HIPAA Security Rule focuses on:", "correct": "Safeguards for electronic PHI", "distractors": ["Only paper records", "Only verbal conversations", "Public health statistics"], "explanation": "HHS Security Rule addresses administrative, physical, and technical safeguards for ePHI.", "references": ["HHS: HIPAA Security Rule — https://www.hhs.gov/hipaa/for-professionals/security/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-infection", "stem": "Hand hygiene is critical before:", "correct": "Preparing or administering injections", "distractors": ["Only after patient contact", "Only when skin is broken", "Only in hospitals"], "explanation": "CDC injection safety materials list hand hygiene before medication preparation.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC: Guideline for Hand Hygiene in Health Care Settings — https://www.cdc.gov/infection-control/hcp/hand-hygiene/index.html"], "difficulty": "beginner"},
    {"topic": "skill-infection", "stem": "Work practice controls under OSHA include:", "correct": "Prohibiting bending or recapping needles by hand", "distractors": ["Reusing gloves all day", "Skipping hand hygiene", "Eating in procedure rooms"], "explanation": "OSHA specifies work practice controls to reduce blood exposure risk.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "skill-infection", "stem": "Unsafe injection practices can transmit:", "correct": "Hepatitis B, hepatitis C, and HIV", "distractors": ["Only bacterial infections", "Only fungal spores from air", "No bloodborne viruses"], "explanation": "CDC documents transmission of bloodborne pathogens from syringe and vial misuse.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "skill-infection", "stem": "Covered entities under HIPAA include:", "correct": "Health plans, clearinghouses, and certain health care providers", "distractors": ["All employers regardless of industry", "Patients and families", "Medical equipment manufacturers only"], "explanation": "HHS defines covered entities subject to Privacy and Security Rules.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "beginner"},
    {"topic": "skill-infection", "stem": "Engineering controls for sharps include:", "correct": "Needleless systems and sharps containers", "distractors": ["Recapping needles routinely", "Carrying syringes in pockets", "Reusing scalpels"], "explanation": "OSHA bloodborne pathogens standard emphasizes engineering controls to reduce needlesticks.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030", "OSHA: Safety and Health Topics — Needlestick Injuries — https://www.osha.gov/needlestick"], "difficulty": "intermediate"},
    {"topic": "skill-terminology", "stem": "Medical assistants typically work:", "correct": "Under provider supervision within scope defined by state law and employer policy", "distractors": ["Independently performing surgery", "Prescribing controlled substances without oversight", "Interpreting all imaging independently"], "explanation": "NHA materials emphasize scope of practice and supervision.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma"], "difficulty": "beginner"},
    {"topic": "skill-terminology", "stem": "Patient identification before procedures should use:", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
