    {"topic": "skill-specimen-lab", "stem": "The order of draw is important to prevent:", "correct": "Cross-contamination of tube additives", "distractors": ["Patient discomfort only", "Slower clotting only", "Larger bruises only"], "explanation": "CLSI GP41 describes order of draw to avoid erroneous results from additive carryover.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "intermediate"},
    {"topic": "skill-specimen-lab", "stem": "The One & Only Campaign reminds clinicians to use:", "correct": "One needle and one syringe only one time per patient", "distractors": ["One syringe for multiple patients if the needle is changed", "Multi-dose vials for any patient", "The same bag of IV fluid for multiple patients"], "explanation": "CDC injection safety emphasizes single-patient use of needles and syringes.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC NPIN: One & Only Campaign — https://npin.cdc.gov/campaign/one-only-campaign"], "difficulty": "beginner"},
    {"topic": "skill-specimen-lab", "stem": "After venipuncture, pressure should be applied:", "correct": "Until hemostasis is achieved without compromising circulation", "distractors": ["Only 5 seconds always", "Not needed with butterfly sets", "Only if patient requests"], "explanation": "Adequate pressure reduces hematoma risk.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "beginner"},
    {"topic": "skill-specimen-lab", "stem": "When should alcohol-based hand rub be used?", "correct": "When hands are not visibly soiled, per facility policy and CDC guidance", "distractors": ["Only after touching blood", "Instead of gloves always", "Never in healthcare"], "explanation": "CDC hand hygiene guidance supports ABHR when hands are not visibly dirty.", "references": ["CDC: Guideline for Hand Hygiene in Health Care Settings — https://www.cdc.gov/infection-control/hcp/hand-hygiene/index.html", "MedlinePlus: Hand-washing — https://medlineplus.gov/ency/article/007425.htm"], "difficulty": "beginner"},
    {"topic": "skill-specimen-lab", "stem": "The order of draw is important to prevent: (scenario 5)", "correct": "Cross-contamination of tube additives", "distractors": ["Patient discomfort only", "Slower clotting only", "Larger bruises only"], "explanation": "CLSI GP41 describes order of draw to avoid erroneous results from additive carryover.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "intermediate"},
    {"topic": "skill-specimen-lab", "stem": "Single-dose medication vials should be:", "correct": "Used for only one patient", "distractors": ["Shared between two patients in the same room", "Recapped and stored for next day", "Used until empty regardless of patients"], "explanation": "CDC injection safety prohibits using single-dose containers for multiple patients.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "skill-specimen-lab", "stem": "After venipuncture, pressure should be applied: (scenario 7)", "correct": "Until hemostasis is achieved without compromising circulation", "distractors": ["Only 5 seconds always", "Not needed with butterfly sets", "Only if patient requests"], "explanation": "Adequate pressure reduces hematoma risk.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "beginner"},
    {"topic": "skill-specimen-lab", "stem": "Facemasks are required when:", "correct": "Injecting into epidural or subdural spaces per CDC", "distractors": ["Giving intramuscular injections routinely", "Every patient encounter", "Only in TB clinics"], "explanation": "CDC safe injection checklist includes mask use for neuraxial procedures.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "advanced"},
    {"topic": "skill-specimen-lab", "stem": "The order of draw is important to prevent: (scenario 9)", "correct": "Cross-contamination of tube additives", "distractors": ["Patient discomfort only", "Slower clotting only", "Larger bruises only"], "explanation": "CLSI GP41 describes order of draw to avoid erroneous results from additive carryover.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "intermediate"},
    {"topic": "skill-specimen-lab", "stem": "Multi-dose vials should ideally be:", "correct": "Dedicated to a single patient when possible", "distractors": ["Left at bedside for convenience", "Shared across a clinic without labeling", "Used without date"], "explanation": "CDC recommends limiting multidose vials and dedicating to one patient when feasible.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "intermediate"},
    {"topic": "skill-specimen-lab", "stem": "After venipuncture, pressure should be applied: (scenario 11)", "correct": "Until hemostasis is achieved without compromising circulation", "distractors": ["Only 5 seconds always", "Not needed with butterfly sets", "Only if patient requests"], "explanation": "Adequate pressure reduces hematoma risk.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "beginner"},
    {"topic": "skill-specimen-lab", "stem": "WHO injection safety aims to:", "correct": "Reduce harm from unnecessary and unsafe injections", "distractors": ["Eliminate all injections globally", "Replace vaccines with oral drugs only", "Ban multidose vials worldwide"], "explanation": "WHO promotes safe, necessary injections as part of infection prevention.", "references": ["WHO: Injection safety — https://www.who.int/teams/integrated-health-services/infection-prevention-control/injection-safety"], "difficulty": "beginner"},
    {"topic": "skill-specimen-lab", "stem": "The order of draw is important to prevent: (scenario 13)", "correct": "Cross-contamination of tube additives", "distractors": ["Patient discomfort only", "Slower clotting only", "Larger bruises only"], "explanation": "CLSI GP41 describes order of draw to avoid erroneous results from additive carryover.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "intermediate"},
    {"topic": "skill-intake", "stem": "OSHA's Bloodborne Pathogens Standard applies to:", "correct": "Occupational exposure to blood and OPIM", "distractors": ["Only hospital physicians", "Only dental offices", "Only laboratory scientists"], "explanation": "29 CFR 1910.1030 covers workers with reasonably anticipated exposure to blood or other potentially infectious materials.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "skill-intake", "stem": "Patient identification before procedures should use:", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "skill-intake", "stem": "Patient should rest quietly for how long before a clinic BP measurement?", "correct": "About 5 minutes when possible", "distractors": ["No rest needed", "At least 30 minutes", "Only 10 seconds"], "explanation": "CDC recommends resting quietly before measurement for consistency.", "references": ["CDC: Measuring Blood Pressure — https://www.cdc.gov/high-blood-pressure/measure/index.html"], "difficulty": "beginner"},
