    {"topic": "skill-intake", "stem": "Medical assistants typically work: (scenario 5)", "correct": "Under provider supervision within scope defined by state law and employer policy", "distractors": ["Independently performing surgery", "Prescribing controlled substances without oversight", "Interpreting all imaging independently"], "explanation": "NHA materials emphasize scope of practice and supervision.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma"], "difficulty": "beginner"},
    {"topic": "skill-intake", "stem": "Documenting vital signs should include:", "correct": "Time, route/site, and patient position when relevant", "distractors": ["Only numeric values without context", "Only if abnormal", "Provider signature only"], "explanation": "Complete documentation supports clinical decisions and continuity.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma"], "difficulty": "beginner"},
    {"topic": "skill-intake", "stem": "Minimum necessary means:", "correct": "Disclose only the PHI needed for the purpose", "distractors": ["Share entire charts for convenience", "Withhold information from patients", "Send all data to marketers"], "explanation": "HIPAA limits uses and disclosures to the minimum necessary standard.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-intake", "stem": "Patient identification before procedures should use: (scenario 8)", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "skill-intake", "stem": "Patient should rest quietly for how long before a clinic BP measurement? (scenario 9)", "correct": "About 5 minutes when possible", "distractors": ["No rest needed", "At least 30 minutes", "Only 10 seconds"], "explanation": "CDC recommends resting quietly before measurement for consistency.", "references": ["CDC: Measuring Blood Pressure — https://www.cdc.gov/high-blood-pressure/measure/index.html"], "difficulty": "beginner"},
    {"topic": "skill-intake", "stem": "Work practice controls under OSHA include:", "correct": "Prohibiting bending or recapping needles by hand", "distractors": ["Reusing gloves all day", "Skipping hand hygiene", "Eating in procedure rooms"], "explanation": "OSHA specifies work practice controls to reduce blood exposure risk.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "skill-intake", "stem": "Medical assistants typically work: (scenario 11)", "correct": "Under provider supervision within scope defined by state law and employer policy", "distractors": ["Independently performing surgery", "Prescribing controlled substances without oversight", "Interpreting all imaging independently"], "explanation": "NHA materials emphasize scope of practice and supervision.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma"], "difficulty": "beginner"},
    {"topic": "skill-intake", "stem": "Documenting vital signs should include: (scenario 12)", "correct": "Time, route/site, and patient position when relevant", "distractors": ["Only numeric values without context", "Only if abnormal", "Provider signature only"], "explanation": "Complete documentation supports clinical decisions and continuity.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma"], "difficulty": "beginner"},
    {"topic": "skill-intake", "stem": "When PHI is used for treatment:", "correct": "HIPAA generally permits disclosure without separate authorization", "distractors": ["Always forbidden", "Requires court order each time", "Requires patient notary"], "explanation": "Treatment, payment, and operations are permitted uses under HIPAA.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-vaccines", "stem": "Vaccines must be stored:", "correct": "Within manufacturer and CDC recommended temperature ranges", "distractors": ["At room temperature indefinitely", "Frozen unless label says otherwise without monitoring", "In direct sunlight"], "explanation": "CDC Vaccine Storage and Handling Toolkit defines cold chain requirements.", "references": ["CDC: Vaccine Storage and Handling Toolkit — https://www.cdc.gov/vaccines/hcp/admin/storage/toolkit/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-vaccines", "stem": "The One & Only Campaign reminds clinicians to use:", "correct": "One needle and one syringe only one time per patient", "distractors": ["One syringe for multiple patients if the needle is changed", "Multi-dose vials for any patient", "The same bag of IV fluid for multiple patients"], "explanation": "CDC injection safety emphasizes single-patient use of needles and syringes.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC NPIN: One & Only Campaign — https://npin.cdc.gov/campaign/one-only-campaign"], "difficulty": "beginner"},
    {"topic": "ccma-vaccines", "stem": "Before administering a vaccine, staff should:", "correct": "Screen for contraindications and precautions per CDC guidance", "distractors": ["Skip screening if patient is in a hurry", "Use expired vaccine if refrigerator was full", "Administer in any muscle regardless of age"], "explanation": "CDC vaccine administration includes screening and valid consent processes.", "references": ["CDC: Vaccine Administration — https://www.cdc.gov/vaccines/hcp/admin/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-vaccines", "stem": "When should alcohol-based hand rub be used?", "correct": "When hands are not visibly soiled, per facility policy and CDC guidance", "distractors": ["Only after touching blood", "Instead of gloves always", "Never in healthcare"], "explanation": "CDC hand hygiene guidance supports ABHR when hands are not visibly dirty.", "references": ["CDC: Guideline for Hand Hygiene in Health Care Settings — https://www.cdc.gov/infection-control/hcp/hand-hygiene/index.html", "MedlinePlus: Hand-washing — https://medlineplus.gov/ency/article/007425.htm"], "difficulty": "beginner"},
    {"topic": "ccma-vaccines", "stem": "Vaccines must be stored:", "correct": "Within manufacturer and CDC recommended temperature ranges", "distractors": ["At room temperature indefinitely", "Frozen unless label says otherwise without monitoring", "In direct sunlight"], "explanation": "CDC Vaccine Storage and Handling Toolkit defines cold chain requirements.", "references": ["CDC: Vaccine Storage and Handling Toolkit — https://www.cdc.gov/vaccines/hcp/admin/storage/toolkit/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-vaccines", "stem": "Single-dose medication vials should be:", "correct": "Used for only one patient", "distractors": ["Shared between two patients in the same room", "Recapped and stored for next day", "Used until empty regardless of patients"], "explanation": "CDC injection safety prohibits using single-dose containers for multiple patients.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "ccma-vaccines", "stem": "Before administering a vaccine, staff should:", "correct": "Screen for contraindications and precautions per CDC guidance", "distractors": ["Skip screening if patient is in a hurry", "Use expired vaccine if refrigerator was full", "Administer in any muscle regardless of age"], "explanation": "CDC vaccine administration includes screening and valid consent processes.", "references": ["CDC: Vaccine Administration — https://www.cdc.gov/vaccines/hcp/admin/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-vaccines", "stem": "Facemasks are required when:", "correct": "Injecting into epidural or subdural spaces per CDC", "distractors": ["Giving intramuscular injections routinely", "Every patient encounter", "Only in TB clinics"], "explanation": "CDC safe injection checklist includes mask use for neuraxial procedures.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "advanced"},
    {"topic": "ccma-vaccines", "stem": "Vaccines must be stored:", "correct": "Within manufacturer and CDC recommended temperature ranges", "distractors": ["At room temperature indefinitely", "Frozen unless label says otherwise without monitoring", "In direct sunlight"], "explanation": "CDC Vaccine Storage and Handling Toolkit defines cold chain requirements.", "references": ["CDC: Vaccine Storage and Handling Toolkit — https://www.cdc.gov/vaccines/hcp/admin/storage/toolkit/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-vaccines", "stem": "Multi-dose vials should ideally be:", "correct": "Dedicated to a single patient when possible", "distractors": ["Left at bedside for convenience", "Shared across a clinic without labeling", "Used without date"], "explanation": "CDC recommends limiting multidose vials and dedicating to one patient when feasible.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "intermediate"},
    {"topic": "ccma-vaccines", "stem": "Before administering a vaccine, staff should:", "correct": "Screen for contraindications and precautions per CDC guidance", "distractors": ["Skip screening if patient is in a hurry", "Use expired vaccine if refrigerator was full", "Administer in any muscle regardless of age"], "explanation": "CDC vaccine administration includes screening and valid consent processes.", "references": ["CDC: Vaccine Administration — https://www.cdc.gov/vaccines/hcp/admin/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-vaccines", "stem": "WHO injection safety aims to:", "correct": "Reduce harm from unnecessary and unsafe injections", "distractors": ["Eliminate all injections globally", "Replace vaccines with oral drugs only", "Ban multidose vials worldwide"], "explanation": "WHO promotes safe, necessary injections as part of infection prevention.", "references": ["WHO: Injection safety — https://www.who.int/teams/integrated-health-services/infection-prevention-control/injection-safety"], "difficulty": "beginner"},
    {"topic": "ccma-hipaa", "stem": "OSHA's Bloodborne Pathogens Standard applies to:", "correct": "Occupational exposure to blood and OPIM", "distractors": ["Only hospital physicians", "Only dental offices", "Only laboratory scientists"], "explanation": "29 CFR 1910.1030 covers workers with reasonably anticipated exposure to blood or other potentially infectious materials.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "An Exposure Control Plan must be:", "correct": "Written and updated annually or when tasks change", "distractors": ["Verbal only", "Optional for small clinics", "Created only after an exposure"], "explanation": "OSHA requires a written exposure control plan for covered employers.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "Hepatitis B vaccination for covered employees must be offered:", "correct": "Within 10 working days of initial assignment unless declined", "distractors": ["Only after a needlestick", "Never if employee refuses paperwork", "Only to nurses"], "explanation": "OSHA mandates HBV vaccination availability for at-risk workers.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "advanced"},
    {"topic": "ccma-hipaa", "stem": "After a needlestick, the first priority is:", "correct": "Wash needlesticks and cuts with soap and water; flush splashes to nose/mouth with water", "distractors": ["Apply a tourniquet", "Wait until end of shift to report", "Squeeze the wound hard"], "explanation": "OSHA post-exposure steps include immediate cleansing and prompt reporting.", "references": ["OSHA: Safety and Health Topics — Needlestick Injuries — https://www.osha.gov/needlestick", "OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "HIPAA protected health information (PHI) is:", "correct": "Individually identifiable health information held or transmitted by covered entities", "distractors": ["Only paper charts", "Only billing data", "De-identified research data only"], "explanation": "The HIPAA Privacy Rule protects identifiable health information with required safeguards.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "beginner"},
    {"topic": "ccma-hipaa", "stem": "Patients have the right under HIPAA to:", "correct": "Access and request amendments to their health records", "distractors": ["Delete all medical records permanently", "Hide records from treating clinicians", "Avoid all disclosures including treatment"], "explanation": "HHS describes individual rights to access, copy, and request correction of PHI.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "Minimum necessary means:", "correct": "Disclose only the PHI needed for the purpose", "distractors": ["Share entire charts for convenience", "Withhold information from patients", "Send all data to marketers"], "explanation": "HIPAA limits uses and disclosures to the minimum necessary standard.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "The HIPAA Security Rule focuses on:", "correct": "Safeguards for electronic PHI", "distractors": ["Only paper records", "Only verbal conversations", "Public health statistics"], "explanation": "HHS Security Rule addresses administrative, physical, and technical safeguards for ePHI.", "references": ["HHS: HIPAA Security Rule — https://www.hhs.gov/hipaa/for-professionals/security/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "A HIPAA authorization is generally required for:", "correct": "Uses and disclosures not otherwise permitted by the Privacy Rule", "distractors": ["Treatment, payment, and health care operations", "Reporting to public health authorities as required by law", "Disclosures to the patient"], "explanation": "Marketing and many non-routine disclosures need patient authorization.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "advanced"},
    {"topic": "ccma-hipaa", "stem": "Work practice controls under OSHA include:", "correct": "Prohibiting bending or recapping needles by hand", "distractors": ["Reusing gloves all day", "Skipping hand hygiene", "Eating in procedure rooms"], "explanation": "OSHA specifies work practice controls to reduce blood exposure risk.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "Sharps injury logs must be maintained:", "correct": "Per OSHA requirements for covered employers", "distractors": ["Only if OSHA inspects", "Only in hospitals", "Never for medical offices"], "explanation": "OSHA bloodborne pathogens standard includes recordkeeping provisions.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "advanced"},
    {"topic": "ccma-hipaa", "stem": "Covered entities under HIPAA include:", "correct": "Health plans, clearinghouses, and certain health care providers", "distractors": ["All employers regardless of industry", "Patients and families", "Medical equipment manufacturers only"], "explanation": "HHS defines covered entities subject to Privacy and Security Rules.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "Standard Precautions apply to:", "correct": "All patient care regardless of diagnosis", "distractors": ["Only patients with known HIV", "Only the operating room", "Only when gloves are worn"], "explanation": "CDC Standard Precautions are the minimum infection prevention practices for all care.", "references": ["CDC: Infection Control in Healthcare Settings (overview) — https://www.cdc.gov/infection-control/hcp/index.html", "CDC/HICPAC: Guideline for Isolation Precautions (2007) — https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "The One & Only Campaign reminds clinicians to use:", "correct": "One needle and one syringe only one time per patient", "distractors": ["One syringe for multiple patients if the needle is changed", "Multi-dose vials for any patient", "The same bag of IV fluid for multiple patients"], "explanation": "CDC injection safety emphasizes single-patient use of needles and syringes.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC NPIN: One & Only Campaign — https://npin.cdc.gov/campaign/one-only-campaign"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "Entering a medication vial with a syringe used on a patient is called:", "correct": "Double dipping and is unsafe", "distractors": ["Standard practice in clinics", "Required for multidose vials", "Allowed if alcohol is used"], "explanation": "CDC lists double dipping among practices that spread bloodborne pathogens.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "intermediate"},
    {"topic": "ccma-transmission", "stem": "When should alcohol-based hand rub be used?", "correct": "When hands are not visibly soiled, per facility policy and CDC guidance", "distractors": ["Only after touching blood", "Instead of gloves always", "Never in healthcare"], "explanation": "CDC hand hygiene guidance supports ABHR when hands are not visibly dirty.", "references": ["CDC: Guideline for Hand Hygiene in Health Care Settings — https://www.cdc.gov/infection-control/hcp/hand-hygiene/index.html", "MedlinePlus: Hand-washing — https://medlineplus.gov/ency/article/007425.htm"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "Transmission-Based Precautions are used:", "correct": "In addition to Standard Precautions for specific pathogens", "distractors": ["Instead of Standard Precautions", "Only in home care", "Only for surgical patients"], "explanation": "Isolation precautions supplement Standard Precautions for certain diseases.", "references": ["CDC/HICPAC: Guideline for Isolation Precautions (2007) — https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-transmission", "stem": "Single-dose medication vials should be:", "correct": "Used for only one patient", "distractors": ["Shared between two patients in the same room", "Recapped and stored for next day", "Used until empty regardless of patients"], "explanation": "CDC injection safety prohibits using single-dose containers for multiple patients.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "A safe injection does not:", "correct": "Harm the patient or expose the provider to avoidable risk", "distractors": ["Require new gloves each time", "Require a witness", "Require written consent"], "explanation": "CDC defines safe injections as those that avoid harm to patients and clinicians.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "Facemasks are required when:", "correct": "Injecting into epidural or subdural spaces per CDC", "distractors": ["Giving intramuscular injections routinely", "Every patient encounter", "Only in TB clinics"], "explanation": "CDC safe injection checklist includes mask use for neuraxial procedures.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "advanced"},
    {"topic": "ccma-transmission", "stem": "Hand hygiene is critical before:", "correct": "Preparing or administering injections", "distractors": ["Only after patient contact", "Only when skin is broken", "Only in hospitals"], "explanation": "CDC injection safety materials list hand hygiene before medication preparation.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC: Guideline for Hand Hygiene in Health Care Settings — https://www.cdc.gov/infection-control/hcp/hand-hygiene/index.html"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "Multi-dose vials should ideally be:", "correct": "Dedicated to a single patient when possible", "distractors": ["Left at bedside for convenience", "Shared across a clinic without labeling", "Used without date"], "explanation": "CDC recommends limiting multidose vials and dedicating to one patient when feasible.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "intermediate"},
    {"topic": "ccma-transmission", "stem": "Unsafe injection practices can transmit:", "correct": "Hepatitis B, hepatitis C, and HIV", "distractors": ["Only bacterial infections", "Only fungal spores from air", "No bloodborne viruses"], "explanation": "CDC documents transmission of bloodborne pathogens from syringe and vial misuse.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "ccma-transmission", "stem": "WHO injection safety aims to:", "correct": "Reduce harm from unnecessary and unsafe injections", "distractors": ["Eliminate all injections globally", "Replace vaccines with oral drugs only", "Ban multidose vials worldwide"], "explanation": "WHO promotes safe, necessary injections as part of infection prevention.", "references": ["WHO: Injection safety — https://www.who.int/teams/integrated-health-services/infection-prevention-control/injection-safety"], "difficulty": "beginner"},
