    {"topic": "skill-emergency-aid", "stem": "Patient identification before procedures should use:", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "skill-emergency-aid", "stem": "AED use should begin:", "correct": "As soon as the device is available while CPR continues", "distractors": ["Only after 10 minutes of CPR", "Only if pulse is present", "Only for children"], "explanation": "Early defibrillation is a key chain-of-survival link for shockable rhythms.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
    {"topic": "skill-emergency-aid", "stem": "Patient identification before procedures should use:", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "phleb-who", "stem": "The order of draw is important to prevent:", "correct": "Cross-contamination of tube additives", "distractors": ["Patient discomfort only", "Slower clotting only", "Larger bruises only"], "explanation": "CLSI GP41 describes order of draw to avoid erroneous results from additive carryover.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "intermediate"},
    {"topic": "phleb-who", "stem": "The One & Only Campaign reminds clinicians to use:", "correct": "One needle and one syringe only one time per patient", "distractors": ["One syringe for multiple patients if the needle is changed", "Multi-dose vials for any patient", "The same bag of IV fluid for multiple patients"], "explanation": "CDC injection safety emphasizes single-patient use of needles and syringes.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC NPIN: One & Only Campaign — https://npin.cdc.gov/campaign/one-only-campaign"], "difficulty": "beginner"},
    {"topic": "phleb-who", "stem": "After venipuncture, pressure should be applied:", "correct": "Until hemostasis is achieved without compromising circulation", "distractors": ["Only 5 seconds always", "Not needed with butterfly sets", "Only if patient requests"], "explanation": "Adequate pressure reduces hematoma risk.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "beginner"},
    {"topic": "phleb-who", "stem": "When should alcohol-based hand rub be used?", "correct": "When hands are not visibly soiled, per facility policy and CDC guidance", "distractors": ["Only after touching blood", "Instead of gloves always", "Never in healthcare"], "explanation": "CDC hand hygiene guidance supports ABHR when hands are not visibly dirty.", "references": ["CDC: Guideline for Hand Hygiene in Health Care Settings — https://www.cdc.gov/infection-control/hcp/hand-hygiene/index.html", "MedlinePlus: Hand-washing — https://medlineplus.gov/ency/article/007425.htm"], "difficulty": "beginner"},
    {"topic": "phleb-who", "stem": "The order of draw is important to prevent:", "correct": "Cross-contamination of tube additives", "distractors": ["Patient discomfort only", "Slower clotting only", "Larger bruises only"], "explanation": "CLSI GP41 describes order of draw to avoid erroneous results from additive carryover.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "intermediate"},
    {"topic": "phleb-who", "stem": "Single-dose medication vials should be:", "correct": "Used for only one patient", "distractors": ["Shared between two patients in the same room", "Recapped and stored for next day", "Used until empty regardless of patients"], "explanation": "CDC injection safety prohibits using single-dose containers for multiple patients.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "phleb-who", "stem": "After venipuncture, pressure should be applied:", "correct": "Until hemostasis is achieved without compromising circulation", "distractors": ["Only 5 seconds always", "Not needed with butterfly sets", "Only if patient requests"], "explanation": "Adequate pressure reduces hematoma risk.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "beginner"},
    {"topic": "phleb-who", "stem": "Facemasks are required when:", "correct": "Injecting into epidural or subdural spaces per CDC", "distractors": ["Giving intramuscular injections routinely", "Every patient encounter", "Only in TB clinics"], "explanation": "CDC safe injection checklist includes mask use for neuraxial procedures.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "advanced"},
    {"topic": "phleb-who", "stem": "The order of draw is important to prevent:", "correct": "Cross-contamination of tube additives", "distractors": ["Patient discomfort only", "Slower clotting only", "Larger bruises only"], "explanation": "CLSI GP41 describes order of draw to avoid erroneous results from additive carryover.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "intermediate"},
    {"topic": "phleb-who", "stem": "Multi-dose vials should ideally be:", "correct": "Dedicated to a single patient when possible", "distractors": ["Left at bedside for convenience", "Shared across a clinic without labeling", "Used without date"], "explanation": "CDC recommends limiting multidose vials and dedicating to one patient when feasible.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "intermediate"},
    {"topic": "phleb-who", "stem": "After venipuncture, pressure should be applied:", "correct": "Until hemostasis is achieved without compromising circulation", "distractors": ["Only 5 seconds always", "Not needed with butterfly sets", "Only if patient requests"], "explanation": "Adequate pressure reduces hematoma risk.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/"], "difficulty": "beginner"},
    {"topic": "phleb-who", "stem": "WHO injection safety aims to:", "correct": "Reduce harm from unnecessary and unsafe injections", "distractors": ["Eliminate all injections globally", "Replace vaccines with oral drugs only", "Ban multidose vials worldwide"], "explanation": "WHO promotes safe, necessary injections as part of infection prevention.", "references": ["WHO: Injection safety — https://www.who.int/teams/integrated-health-services/infection-prevention-control/injection-safety"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "Adult CPR compression rate should be:", "correct": "100 to 120 compressions per minute", "distractors": ["60 to 80 per minute", "150 to 180 per minute", "As fast as possible without limit"], "explanation": "AHA recommends 100–120/min for adult compressions.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "Adult compression depth should be at least:", "correct": "2 inches (5 cm) without exceeding 2.4 inches (6 cm)", "distractors": ["1 inch always", "3 inches minimum", "Depth does not matter"], "explanation": "AHA adult BLS guidance specifies depth at least 2 inches while avoiding excessive depth.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "High-quality CPR includes chest compression fraction:", "correct": "Greater than 80% when possible", "distractors": ["Less than 20%", "Exactly 50% always", "Only during shockable rhythms"], "explanation": "AHA high-quality CPR metrics include CCF >80%.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "intermediate"},
    {"topic": "ekg-acls-basics", "stem": "Compression-to-ventilation ratio for adult BLS with advanced airway not in place is:", "correct": "30:2", "distractors": ["15:2 for all adults", "5:1", "Continuous breaths without compressions"], "explanation": "AHA conventional CPR uses 30:2 for adults.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "Minimizing interruptions in chest compressions helps:", "correct": "Maintain perfusion and improve outcomes", "distractors": ["Reduce rescuer fatigue only", "Eliminate need for defibrillation", "Replace need for epinephrine"], "explanation": "AHA emphasizes minimizing pauses to improve coronary perfusion pressure.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support", "American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "intermediate"},
    {"topic": "ekg-acls-basics", "stem": "Allowing full chest recoil means:", "correct": "Letting the chest return to normal position between compressions", "distractors": ["Leaning on the chest continuously", "Removing hands for 5 seconds", "Hyperextending the spine"], "explanation": "Full recoil allows heart chambers to refill.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "Rescuers should switch compressors about every:", "correct": "2 minutes or sooner if fatigued", "distractors": ["10 seconds", "15 minutes", "Never switch"], "explanation": "AHA algorithms recommend rotating compressors to maintain quality.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "intermediate"},
    {"topic": "ekg-acls-basics", "stem": "Excessive ventilation during CPR can:", "correct": "Increase intrathoracic pressure and reduce venous return", "distractors": ["Improve outcomes always", "Replace compressions", "Prevent gastric distension entirely"], "explanation": "AHA warns against excessive ventilation during resuscitation.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "advanced"},
    {"topic": "ekg-acls-basics", "stem": "If an advanced airway is in place during adult CPR, ventilations are typically:", "correct": "1 breath every 6 seconds without pausing compressions", "distractors": ["30:2 ratio still required", "No breaths ever", "1 breath every 30 seconds only"], "explanation": "AHA ACLS algorithm lists 10 breaths/min (every 6 s) with continuous compressions.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "advanced"},
    {"topic": "ekg-acls-basics", "stem": "The first link in the adult out-of-hospital Chain of Survival is:", "correct": "Recognition of cardiac arrest and activation of emergency response", "distractors": ["Defibrillation before compressions always", "Medication administration", "Cooling"], "explanation": "Early recognition and EMS activation enable timely BLS and defibrillation.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "AED use should begin:", "correct": "As soon as the device is available while CPR continues", "distractors": ["Only after 10 minutes of CPR", "Only if pulse is present", "Only for children"], "explanation": "Early defibrillation is a key chain-of-survival link for shockable rhythms.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "CPR should be started on an unresponsive patient who:", "correct": "Is not breathing normally or only gasping", "distractors": ["Has a weak pulse always", "Is speaking", "Has chest pain only"], "explanation": "AHA teaches checking responsiveness and breathing before starting compressions.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
