    {"topic": "ccma-transmission", "stem": "Standard Precautions apply to: (review 1)", "correct": "All patient care regardless of diagnosis", "distractors": ["Only patients with known HIV", "Only the operating room", "Only when gloves are worn"], "explanation": "CDC Standard Precautions are the minimum infection prevention practices for all care.", "references": ["CDC: Infection Control in Healthcare Settings (overview) — https://www.cdc.gov/infection-control/hcp/index.html", "CDC/HICPAC: Guideline for Isolation Precautions (2007) — https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "The One & Only Campaign reminds clinicians to use: (review 2)", "correct": "One needle and one syringe only one time per patient", "distractors": ["One syringe for multiple patients if the needle is changed", "Multi-dose vials for any patient", "The same bag of IV fluid for multiple patients"], "explanation": "CDC injection safety emphasizes single-patient use of needles and syringes.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC NPIN: One & Only Campaign — https://npin.cdc.gov/campaign/one-only-campaign"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "Entering a medication vial with a syringe used on a patient is called: (review 3)", "correct": "Double dipping and is unsafe", "distractors": ["Standard practice in clinics", "Required for multidose vials", "Allowed if alcohol is used"], "explanation": "CDC lists double dipping among practices that spread bloodborne pathogens.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "intermediate"},
    {"topic": "ccma-transmission", "stem": "When should alcohol-based hand rub be used? (review 4)", "correct": "When hands are not visibly soiled, per facility policy and CDC guidance", "distractors": ["Only after touching blood", "Instead of gloves always", "Never in healthcare"], "explanation": "CDC hand hygiene guidance supports ABHR when hands are not visibly dirty.", "references": ["CDC: Guideline for Hand Hygiene in Health Care Settings — https://www.cdc.gov/infection-control/hcp/hand-hygiene/index.html", "MedlinePlus: Hand-washing — https://medlineplus.gov/ency/article/007425.htm"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "Transmission-Based Precautions are used: (review 5)", "correct": "In addition to Standard Precautions for specific pathogens", "distractors": ["Instead of Standard Precautions", "Only in home care", "Only for surgical patients"], "explanation": "Isolation precautions supplement Standard Precautions for certain diseases.", "references": ["CDC/HICPAC: Guideline for Isolation Precautions (2007) — https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-transmission", "stem": "Single-dose medication vials should be: (review 6)", "correct": "Used for only one patient", "distractors": ["Shared between two patients in the same room", "Recapped and stored for next day", "Used until empty regardless of patients"], "explanation": "CDC injection safety prohibits using single-dose containers for multiple patients.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "A safe injection does not: (review 7)", "correct": "Harm the patient or expose the provider to avoidable risk", "distractors": ["Require new gloves each time", "Require a witness", "Require written consent"], "explanation": "CDC defines safe injections as those that avoid harm to patients and clinicians.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "ccma-transmission", "stem": "Facemasks are required when: (review 8)", "correct": "Injecting into epidural or subdural spaces per CDC", "distractors": ["Giving intramuscular injections routinely", "Every patient encounter", "Only in TB clinics"], "explanation": "CDC safe injection checklist includes mask use for neuraxial procedures.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "advanced"},
    {"topic": "ccma-vaccines", "stem": "Vaccines must be stored: (review 1)", "correct": "Within manufacturer and CDC recommended temperature ranges", "distractors": ["At room temperature indefinitely", "Frozen unless label says otherwise without monitoring", "In direct sunlight"], "explanation": "CDC Vaccine Storage and Handling Toolkit defines cold chain requirements.", "references": ["CDC: Vaccine Storage and Handling Toolkit — https://www.cdc.gov/vaccines/hcp/admin/storage/toolkit/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-vaccines", "stem": "The One & Only Campaign reminds clinicians to use: (review 2)", "correct": "One needle and one syringe only one time per patient", "distractors": ["One syringe for multiple patients if the needle is changed", "Multi-dose vials for any patient", "The same bag of IV fluid for multiple patients"], "explanation": "CDC injection safety emphasizes single-patient use of needles and syringes.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC NPIN: One & Only Campaign — https://npin.cdc.gov/campaign/one-only-campaign"], "difficulty": "beginner"},
    {"topic": "ccma-vaccines", "stem": "Before administering a vaccine, staff should: (review 3)", "correct": "Screen for contraindications and precautions per CDC guidance", "distractors": ["Skip screening if patient is in a hurry", "Use expired vaccine if refrigerator was full", "Administer in any muscle regardless of age"], "explanation": "CDC vaccine administration includes screening and valid consent processes.", "references": ["CDC: Vaccine Administration — https://www.cdc.gov/vaccines/hcp/admin/index.html"], "difficulty": "intermediate"},
