    {"topic": "skill-poct", "stem": "Medical assistants typically work: (review 1)", "correct": "Under provider supervision within scope defined by state law and employer policy", "distractors": ["Independently performing surgery", "Prescribing controlled substances without oversight", "Interpreting all imaging independently"], "explanation": "NHA materials emphasize scope of practice and supervision.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma"], "difficulty": "beginner"},
    {"topic": "skill-poct", "stem": "Venipuncture site selection should avoid: (review 2)", "correct": "Areas with IV fluids, infection, or lymphedema when possible", "distractors": ["The antecubital fossa entirely", "All veins on the dominant arm", "Tourniquet use"], "explanation": "CLSI and safety guidance recommend assessing site suitability.", "references": ["CLSI: GP41 Collection of Diagnostic Venous Blood Specimens — https://clsi.org/standards/products/general-laboratory-and-infection-control/documents/gp41/", "WHO: Injection safety — https://www.who.int/teams/integrated-health-services/infection-prevention-control/injection-safety"], "difficulty": "intermediate"},
