    {"topic": "phleb-who", "stem": "Facemasks are required when: (review 8)", "correct": "Injecting into epidural or subdural spaces per CDC", "distractors": ["Giving intramuscular injections routinely", "Every patient encounter", "Only in TB clinics"], "explanation": "CDC safe injection checklist includes mask use for neuraxial procedures.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "advanced"},
    {"topic": "ekg-acls-basics", "stem": "Adult CPR compression rate should be: (review 1)", "correct": "100 to 120 compressions per minute", "distractors": ["60 to 80 per minute", "150 to 180 per minute", "As fast as possible without limit"], "explanation": "AHA recommends 100–120/min for adult compressions.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "Adult compression depth should be at least: (review 2)", "correct": "2 inches (5 cm) without exceeding 2.4 inches (6 cm)", "distractors": ["1 inch always", "3 inches minimum", "Depth does not matter"], "explanation": "AHA adult BLS guidance specifies depth at least 2 inches while avoiding excessive depth.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "High-quality CPR includes chest compression fraction: (review 3)", "correct": "Greater than 80% when possible", "distractors": ["Less than 20%", "Exactly 50% always", "Only during shockable rhythms"], "explanation": "AHA high-quality CPR metrics include CCF >80%.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "intermediate"},
    {"topic": "ekg-acls-basics", "stem": "Compression-to-ventilation ratio for adult BLS with advanced airway not in place is: (review 4)", "correct": "30:2", "distractors": ["15:2 for all adults", "5:1", "Continuous breaths without compressions"], "explanation": "AHA conventional CPR uses 30:2 for adults.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "Minimizing interruptions in chest compressions helps: (review 5)", "correct": "Maintain perfusion and improve outcomes", "distractors": ["Reduce rescuer fatigue only", "Eliminate need for defibrillation", "Replace need for epinephrine"], "explanation": "AHA emphasizes minimizing pauses to improve coronary perfusion pressure.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support", "American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "intermediate"},
    {"topic": "ekg-acls-basics", "stem": "Allowing full chest recoil means: (review 6)", "correct": "Letting the chest return to normal position between compressions", "distractors": ["Leaning on the chest continuously", "Removing hands for 5 seconds", "Hyperextending the spine"], "explanation": "Full recoil allows heart chambers to refill.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "beginner"},
    {"topic": "ekg-acls-basics", "stem": "Rescuers should switch compressors about every: (review 7)", "correct": "2 minutes or sooner if fatigued", "distractors": ["10 seconds", "15 minutes", "Never switch"], "explanation": "AHA algorithms recommend rotating compressors to maintain quality.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "intermediate"},
    {"topic": "ekg-acls-basics", "stem": "Excessive ventilation during CPR can: (review 8)", "correct": "Increase intrathoracic pressure and reduce venous return", "distractors": ["Improve outcomes always", "Replace compressions", "Prevent gastric distension entirely"], "explanation": "AHA warns against excessive ventilation during resuscitation.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "advanced"},
    {"topic": "skill-osha-bbp", "stem": "OSHA's Bloodborne Pathogens Standard applies to: (review 1)", "correct": "Occupational exposure to blood and OPIM", "distractors": ["Only hospital physicians", "Only dental offices", "Only laboratory scientists"], "explanation": "29 CFR 1910.1030 covers workers with reasonably anticipated exposure to blood or other potentially infectious materials.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "skill-osha-bbp", "stem": "The One & Only Campaign reminds clinicians to use: (review 2)", "correct": "One needle and one syringe only one time per patient", "distractors": ["One syringe for multiple patients if the needle is changed", "Multi-dose vials for any patient", "The same bag of IV fluid for multiple patients"], "explanation": "CDC injection safety emphasizes single-patient use of needles and syringes.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/", "CDC NPIN: One & Only Campaign — https://npin.cdc.gov/campaign/one-only-campaign"], "difficulty": "beginner"},
    {"topic": "skill-osha-bbp", "stem": "Hepatitis B vaccination for covered employees must be offered: (review 3)", "correct": "Within 10 working days of initial assignment unless declined", "distractors": ["Only after a needlestick", "Never if employee refuses paperwork", "Only to nurses"], "explanation": "OSHA mandates HBV vaccination availability for at-risk workers.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "advanced"},
    {"topic": "skill-osha-bbp", "stem": "When should alcohol-based hand rub be used? (review 4)", "correct": "When hands are not visibly soiled, per facility policy and CDC guidance", "distractors": ["Only after touching blood", "Instead of gloves always", "Never in healthcare"], "explanation": "CDC hand hygiene guidance supports ABHR when hands are not visibly dirty.", "references": ["CDC: Guideline for Hand Hygiene in Health Care Settings — https://www.cdc.gov/infection-control/hcp/hand-hygiene/index.html", "MedlinePlus: Hand-washing — https://medlineplus.gov/ency/article/007425.htm"], "difficulty": "beginner"},
    {"topic": "skill-osha-bbp", "stem": "HIPAA protected health information (PHI) is: (review 5)", "correct": "Individually identifiable health information held or transmitted by covered entities", "distractors": ["Only paper charts", "Only billing data", "De-identified research data only"], "explanation": "The HIPAA Privacy Rule protects identifiable health information with required safeguards.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "beginner"},
    {"topic": "skill-osha-bbp", "stem": "Single-dose medication vials should be: (review 6)", "correct": "Used for only one patient", "distractors": ["Shared between two patients in the same room", "Recapped and stored for next day", "Used until empty regardless of patients"], "explanation": "CDC injection safety prohibits using single-dose containers for multiple patients.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "skill-osha-bbp", "stem": "Minimum necessary means: (review 7)", "correct": "Disclose only the PHI needed for the purpose", "distractors": ["Share entire charts for convenience", "Withhold information from patients", "Send all data to marketers"], "explanation": "HIPAA limits uses and disclosures to the minimum necessary standard.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-osha-bbp", "stem": "Facemasks are required when: (review 8)", "correct": "Injecting into epidural or subdural spaces per CDC", "distractors": ["Giving intramuscular injections routinely", "Every patient encounter", "Only in TB clinics"], "explanation": "CDC safe injection checklist includes mask use for neuraxial procedures.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "advanced"},
