    {"topic": "skill-med-safety", "stem": "High-alert medications require: (review 1)", "correct": "Extra precautions per institutional policy", "distractors": ["No special labeling", "Verbal orders only", "Storage in patient rooms unlocked"], "explanation": "FDA medication safety resources highlight risk reduction strategies.", "references": ["FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "intermediate"},
