    {"topic": "skill-wound-care", "stem": "Standard Precautions apply to: (review 1)", "correct": "All patient care regardless of diagnosis", "distractors": ["Only patients with known HIV", "Only the operating room", "Only when gloves are worn"], "explanation": "CDC Standard Precautions are the minimum infection prevention practices for all care.", "references": ["CDC: Infection Control in Healthcare Settings (overview) — https://www.cdc.gov/infection-control/hcp/index.html", "CDC/HICPAC: Guideline for Isolation Precautions (2007) — https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"], "difficulty": "beginner"},
    {"topic": "skill-wound-care", "stem": "Patient identification before procedures should use: (review 2)", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "skill-wound-care", "stem": "Entering a medication vial with a syringe used on a patient is called: (review 3)", "correct": "Double dipping and is unsafe", "distractors": ["Standard practice in clinics", "Required for multidose vials", "Allowed if alcohol is used"], "explanation": "CDC lists double dipping among practices that spread bloodborne pathogens.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "intermediate"},
    {"topic": "skill-wound-care", "stem": "Patient identification before procedures should use: (review 4)", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "skill-wound-care", "stem": "Transmission-Based Precautions are used: (review 5)", "correct": "In addition to Standard Precautions for specific pathogens", "distractors": ["Instead of Standard Precautions", "Only in home care", "Only for surgical patients"], "explanation": "Isolation precautions supplement Standard Precautions for certain diseases.", "references": ["CDC/HICPAC: Guideline for Isolation Precautions (2007) — https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"], "difficulty": "intermediate"},
    {"topic": "skill-wound-care", "stem": "Patient identification before procedures should use: (review 6)", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "skill-wound-care", "stem": "A safe injection does not: (review 7)", "correct": "Harm the patient or expose the provider to avoidable risk", "distractors": ["Require new gloves each time", "Require a witness", "Require written consent"], "explanation": "CDC defines safe injections as those that avoid harm to patients and clinicians.", "references": ["CDC: Preventing Unsafe Injection Practices — https://www.cdc.gov/injection-safety/hcp/clinical-safety/"], "difficulty": "beginner"},
    {"topic": "skill-wound-care", "stem": "Patient identification before procedures should use: (review 8)", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "skill-emergency-aid", "stem": "Adult CPR compression rate should be: (review 1)", "correct": "100 to 120 compressions per minute", "distractors": ["60 to 80 per minute", "150 to 180 per minute", "As fast as possible without limit"], "explanation": "AHA recommends 100–120/min for adult compressions.", "references": ["American Heart Association: What is CPR — https://cpr.heart.org/en/resources/what-is-cpr", "American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "beginner"},
    {"topic": "skill-emergency-aid", "stem": "Patient identification before procedures should use: (review 2)", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "skill-emergency-aid", "stem": "High-quality CPR includes chest compression fraction: (review 3)", "correct": "Greater than 80% when possible", "distractors": ["Less than 20%", "Exactly 50% always", "Only during shockable rhythms"], "explanation": "AHA high-quality CPR metrics include CCF >80%.", "references": ["American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "intermediate"},
    {"topic": "skill-emergency-aid", "stem": "Patient identification before procedures should use: (review 4)", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "skill-emergency-aid", "stem": "Minimizing interruptions in chest compressions helps: (review 5)", "correct": "Maintain perfusion and improve outcomes", "distractors": ["Reduce rescuer fatigue only", "Eliminate need for defibrillation", "Replace need for epinephrine"], "explanation": "AHA emphasizes minimizing pauses to improve coronary perfusion pressure.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support", "American Heart Association: High-Quality CPR — https://cpr.heart.org/en/resuscitation-science/high-quality-cpr"], "difficulty": "intermediate"},
    {"topic": "skill-emergency-aid", "stem": "Patient identification before procedures should use: (review 6)", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "skill-emergency-aid", "stem": "Rescuers should switch compressors about every: (review 7)", "correct": "2 minutes or sooner if fatigued", "distractors": ["10 seconds", "15 minutes", "Never switch"], "explanation": "AHA algorithms recommend rotating compressors to maintain quality.", "references": ["American Heart Association: Adult Basic Life Support Guidelines — https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "difficulty": "intermediate"},
    {"topic": "skill-emergency-aid", "stem": "Patient identification before procedures should use: (review 8)", "correct": "At least two identifiers per facility policy", "distractors": ["Room number alone", "First name only", "Clothing description"], "explanation": "Two-identifier verification is a standard safety practice.", "references": ["NHA: CCMA certification — https://www.nhanow.com/certifications/ccma", "FDA: Medication Safety Program — https://www.fda.gov/drugs/medication-safety-program"], "difficulty": "beginner"},
    {"topic": "ccma-hipaa", "stem": "OSHA's Bloodborne Pathogens Standard applies to: (review 1)", "correct": "Occupational exposure to blood and OPIM", "distractors": ["Only hospital physicians", "Only dental offices", "Only laboratory scientists"], "explanation": "29 CFR 1910.1030 covers workers with reasonably anticipated exposure to blood or other potentially infectious materials.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "An Exposure Control Plan must be: (review 2)", "correct": "Written and updated annually or when tasks change", "distractors": ["Verbal only", "Optional for small clinics", "Created only after an exposure"], "explanation": "OSHA requires a written exposure control plan for covered employers.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "Hepatitis B vaccination for covered employees must be offered: (review 3)", "correct": "Within 10 working days of initial assignment unless declined", "distractors": ["Only after a needlestick", "Never if employee refuses paperwork", "Only to nurses"], "explanation": "OSHA mandates HBV vaccination availability for at-risk workers.", "references": ["OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "advanced"},
    {"topic": "ccma-hipaa", "stem": "After a needlestick, the first priority is: (review 4)", "correct": "Wash needlesticks and cuts with soap and water; flush splashes to nose/mouth with water", "distractors": ["Apply a tourniquet", "Wait until end of shift to report", "Squeeze the wound hard"], "explanation": "OSHA post-exposure steps include immediate cleansing and prompt reporting.", "references": ["OSHA: Safety and Health Topics — Needlestick Injuries — https://www.osha.gov/needlestick", "OSHA: Bloodborne Pathogens Standard (29 CFR 1910.1030) — https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1030"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "HIPAA protected health information (PHI) is: (review 5)", "correct": "Individually identifiable health information held or transmitted by covered entities", "distractors": ["Only paper charts", "Only billing data", "De-identified research data only"], "explanation": "The HIPAA Privacy Rule protects identifiable health information with required safeguards.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "beginner"},
    {"topic": "ccma-hipaa", "stem": "Patients have the right under HIPAA to: (review 6)", "correct": "Access and request amendments to their health records", "distractors": ["Delete all medical records permanently", "Hide records from treating clinicians", "Avoid all disclosures including treatment"], "explanation": "HHS describes individual rights to access, copy, and request correction of PHI.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "Minimum necessary means: (review 7)", "correct": "Disclose only the PHI needed for the purpose", "distractors": ["Share entire charts for convenience", "Withhold information from patients", "Send all data to marketers"], "explanation": "HIPAA limits uses and disclosures to the minimum necessary standard.", "references": ["HHS: HIPAA Privacy Rule — https://www.hhs.gov/hipaa/for-professionals/privacy/index.html"], "difficulty": "intermediate"},
    {"topic": "ccma-hipaa", "stem": "The HIPAA Security Rule focuses on: (review 8)", "correct": "Safeguards for electronic PHI", "distractors": ["Only paper records", "Only verbal conversations", "Public health statistics"], "explanation": "HHS Security Rule addresses administrative, physical, and technical safeguards for ePHI.", "references": ["HHS: HIPAA Security Rule — https://www.hhs.gov/hipaa/for-professionals/security/index.html"], "difficulty": "intermediate"},
